_ICON_QIcon = None

def get_app_icon():
    global _ICON_QIcon
    if _ICON_QIcon is not None:
        return _ICON_QIcon
    try:
        data = base64.b64decode(ICON_B64)
        pix = QPixmap()
        pix.loadFromData(data)
        _ICON_QIcon = QIcon(pix)
    except Exception:
        _ICON_QIcon = QIcon()
    return _ICON_QIcon


def get_tray_pixmap():
    try:
        data = base64.b64decode(ICON_B64)
        pix = QPixmap()
        pix.loadFromData(data)
        return pix.scaled(32, 32, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    except Exception:
        pix = QPixmap(32, 32)
        pix.fill(Qt.transparent)
        p = QPainter(pix)
        p.setRenderHint(QPainter.Antialiasing)
        pen = QPen(QColor("#6868cc"), 2)
        pen.setCapStyle(Qt.RoundCap)
        p.setPen(pen)
        p.drawLine(16, 4, 16, 28)
        p.drawLine(4, 16, 28, 16)
        p.end()
        return pix


def load_settings():
    if os.path.exists(SETTINGS_FILE):
        try:
            with open(SETTINGS_FILE, "r") as f:
                data = json.load(f)
            merged = DEFAULT_SETTINGS.copy()
            merged.update(data)
            if "profiles" not in merged:
                merged["profiles"] = {}
            return merged
        except Exception:
            pass
    return DEFAULT_SETTINGS.copy()


def save_settings(settings):
    try:
        with open(SETTINGS_FILE, "w") as f:
            json.dump(settings, f, indent=4, ensure_ascii=False)
    except Exception:
        pass


def extract_profile(settings):
    return {k: settings[k] for k in PROFILE_KEYS if k in settings}


def make_spinbox(val, mn, mx, decimals=2, step=0.5, width=110):
    sb = QDoubleSpinBox()
    sb.setDecimals(decimals)
    sb.setSingleStep(step)
    sb.setRange(mn, mx)
    sb.setValue(float(val))
    sb.setFixedWidth(width)
    return sb


def build_overlay_flags(overlay_type):
    base = Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool
    if overlay_type == "real":
        return base | Qt.X11BypassWindowManagerHint
    elif overlay_type == "borderless":
        return Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint
    elif overlay_type == "topmost":
        return Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool
    else:
        return base | Qt.X11BypassWindowManagerHint


class HotkeySignals(QObject):
    toggle_panel = pyqtSignal()
    toggle_clickthrough = pyqtSignal()


def draw_crosshair(p, cx, cy, s, preview_scale=1.0):
    col = QColor(s["color"])
    col.setAlpha(int(s["alpha"]))
    oc = QColor(s["outline_color"])
    oc.setAlpha(int(s["alpha"]))
    th = float(s["thickness"])
    sz = float(s["size"]) * preview_scale
    gap = float(s["gap"]) * preview_scale
    ds = float(s["dot_size"]) * preview_scale
    mode = s["mode"]
    oth = float(s.get("outline_thickness", 1.0))
    ext_len = float(s.get("outline_ext_len", 5.0)) * preview_scale
    ext_gap = float(s.get("outline_ext_gap", 2.0)) * preview_scale

    if s.get("outline"):
        op = QPen(oc, th + oth * 2)
        op.setCapStyle(Qt.RoundCap)
        p.setPen(op)
        _draw_shape(p, cx, cy, mode, sz, gap, th, ds, s, preview_scale)

    pen = QPen(col, th)
    pen.setCapStyle(Qt.RoundCap)
    p.setPen(pen)
    _draw_shape(p, cx, cy, mode, sz, gap, th, ds, s, preview_scale)

    if s.get("outline_ext", False):
        ext_pen = QPen(oc, th)
        ext_pen.setCapStyle(Qt.RoundCap)
        p.setPen(ext_pen)
        _draw_ext_lines(p, cx, cy, sz, ext_len, ext_gap)


def _draw_ext_lines(p, cx, cy, sz, ext_len, ext_gap):
    start = sz + ext_gap
    end = sz + ext_gap + ext_len
    p.drawLine(int(cx - end), cy, int(cx - start), cy)
    p.drawLine(int(cx + start), cy, int(cx + end), cy)
    p.drawLine(cx, int(cy - end), cx, int(cy - start))
    p.drawLine(cx, int(cy + start), cx, int(cy + end))


def _draw_shape(p, cx, cy, mode, sz, gap, th, ds, s, scale=1.0):
    if mode == "dot":
        p.setBrush(QBrush(p.pen().color()))
        p.setPen(Qt.NoPen)
        p.drawEllipse(int(cx - ds), int(cy - ds), int(ds * 2), int(ds * 2))
        p.setPen(QPen(p.brush().color(), th))
        p.setBrush(Qt.NoBrush)
    elif mode == "ring":
        outer = sz
        inner = max(0.0, sz - th * 2)
        path = QPainterPath()
        path.addEllipse(QRectF(cx - outer, cy - outer, outer * 2, outer * 2))
        path.addEllipse(QRectF(cx - inner, cy - inner, inner * 2, inner * 2))
        p.setBrush(QBrush(p.pen().color()))
        p.setPen(Qt.NoPen)
        p.fillPath(path, QBrush(p.brush().color()))
        p.setPen(QPen(p.brush().color(), th))
        p.setBrush(Qt.NoBrush)
    elif mode in ("cross", "cross+dot"):
        p.drawLine(int(cx - sz), cy, int(cx - gap), cy)
        p.drawLine(int(cx + gap), cy, int(cx + sz), cy)
        if not s.get("t_shape"):
            p.drawLine(cx, int(cy - sz), cx, int(cy - gap))
        p.drawLine(cx, int(cy + gap), cx, int(cy + sz))
        if mode == "cross+dot" or s.get("center_dot"):
            saved = p.pen()
            p.setBrush(QBrush(saved.color()))
            p.setPen(Qt.NoPen)
            p.drawEllipse(int(cx - ds), int(cy - ds), int(ds * 2), int(ds * 2))
            p.setPen(saved)
            p.setBrush(Qt.NoBrush)
    elif mode == "circle":
        p.drawEllipse(int(cx - sz), int(cy - sz), int(sz * 2), int(sz * 2))
    elif mode == "circle+dot":
        p.drawEllipse(int(cx - sz), int(cy - sz), int(sz * 2), int(sz * 2))
        saved = p.pen()
        p.setBrush(QBrush(saved.color()))
        p.setPen(Qt.NoPen)
        p.drawEllipse(int(cx - ds), int(cy - ds), int(ds * 2), int(ds * 2))
        p.setPen(saved)
        p.setBrush(Qt.NoBrush)
    elif mode == "x":
        p.drawLine(int(cx - sz), int(cy - sz), int(cx - gap), int(cy - gap))
        p.drawLine(int(cx + gap), int(cy + gap), int(cx + sz), int(cy + sz))
        p.drawLine(int(cx + sz), int(cy - sz), int(cx + gap), int(cy - gap))
        p.drawLine(int(cx - gap), int(cy + gap), int(cx - sz), int(cy + sz))
    elif mode == "T":
        p.drawLine(int(cx - sz), cy, int(cx + sz), cy)
        p.drawLine(cx, cy, cx, int(cy + sz))
    elif mode == "chevron":
        p.drawLine(int(cx - sz), int(cy + sz // 2), cx, int(cy - sz // 2))
        p.drawLine(cx, int(cy - sz // 2), int(cx + sz), int(cy + sz // 2))
    elif mode == "ngon3":
        import math
        pts = []
        for i in range(3):
            a = math.radians(i * 120 - 90)
            pts.append((int(cx + sz * math.cos(a)), int(cy + sz * math.sin(a))))
        for i in range(3):
            x1, y1 = pts[i]
            x2, y2 = pts[(i + 1) % 3]
            p.drawLine(x1, y1, x2, y2)

    if s.get("center_dot") and mode not in ("dot", "cross+dot", "circle+dot", "ring"):
        saved = p.pen()
        p.setBrush(QBrush(saved.color()))
        p.setPen(Qt.NoPen)
        p.drawEllipse(int(cx - ds), int(cy - ds), int(ds * 2), int(ds * 2))
        p.setPen(saved)
        p.setBrush(Qt.NoBrush)


class CrosshairWidget(QWidget):
    def __init__(self, settings):
        super().__init__()
        self.settings = settings
        screen = QApplication.primaryScreen().geometry()
        self.sw = screen.width()
        self.sh = screen.height()
        self._apply_overlay_flags()
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setGeometry(screen)
        self.show()

    def _apply_overlay_flags(self):
        ot = self.settings.get("overlay_type", "simple")
        flags = build_overlay_flags(ot)
        self.setWindowFlags(flags)

    def recenter(self):
        screen = QApplication.primaryScreen().geometry()
        self.sw = screen.width()
        self.sh = screen.height()
        self.setGeometry(screen)
        self.update()

    def reload_overlay(self):
        self.hide()
        self._apply_overlay_flags()
        screen = QApplication.primaryScreen().geometry()
        self.setGeometry(screen)
        self.show()
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        cx = int(self.sw / 2 + self.settings["x_offset"])
        cy = int(self.sh / 2 + self.settings["y_offset"])
        draw_crosshair(p, cx, cy, self.settings)


class CrosshairPreview(QWidget):
    def __init__(self, settings, parent=None):
        super().__init__(parent)
        self.settings = settings
        self.setFixedSize(190, 190)
        self.setStyleSheet("background: #0a0a18; border: 1px solid #3a3a5c; border-radius: 6px;")

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        cx = self.width() // 2
        cy = self.height() // 2
        sc = min(1.0, 70.0 / max(float(self.settings.get("size", 20)), 1))
        draw_crosshair(p, cx, cy, self.settings, preview_scale=sc)


class HotkeyButton(QPushButton):
    def __init__(self, key_text, parent=None):
        super().__init__(key_text, parent)
        self._listening = False
        self.setFixedWidth(130)
        self._KEY_MAP = {
            Qt.Key_F1: "F1", Qt.Key_F2: "F2", Qt.Key_F3: "F3",
            Qt.Key_F4: "F4", Qt.Key_F5: "F5", Qt.Key_F6: "F6",
            Qt.Key_F7: "F7", Qt.Key_F8: "F8", Qt.Key_F9: "F9",
            Qt.Key_F10: "F10", Qt.Key_F11: "F11", Qt.Key_F12: "F12",
            Qt.Key_Escape: "Escape", Qt.Key_Delete: "Delete",
            Qt.Key_Insert: "Insert", Qt.Key_Home: "Home",
            Qt.Key_End: "End", Qt.Key_PageUp: "Page Up",
            Qt.Key_PageDown: "Page Down",
        }

    def start_listen(self):
        self._listening = True
        self.setText("Нажмите клавишу...")
        self.setStyleSheet(
            "background: #1e1e38; color: #f9e2af; border: 1px solid #f9e2af; border-radius: 5px;"
        )

    def keyPressEvent(self, event):
        if self._listening:
            key = event.text().upper() if event.text().strip() else ""
            if not key:
                key = self._KEY_MAP.get(event.key(), "")
            if key:
                self.setText(key)
                self._listening = False
                self.setStyleSheet("")
            return
        super().keyPressEvent(event)

    def focusOutEvent(self, event):
        if self._listening:
            self._listening = False
            self.setStyleSheet("")
        super().focusOutEvent(event)


class HotkeyDialog(QDialog):
    def __init__(self, settings, parent=None):
        super().__init__(parent)
        self.settings = settings
        self.setWindowTitle("Горячие клавиши")
        self.setFixedWidth(480)
        self.setWindowFlags(self.windowFlags() & ~Qt.WindowContextHelpButtonHint)
        self.setStyleSheet(STYLE)
        self.setWindowIcon(get_app_icon())
        self._build()

    def _build(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(12)

        title = QLabel("Настройка горячих клавиш")
        title.setStyleSheet("font-size: 14px; font-weight: bold; color: #9090ff;")
        layout.addWidget(title)

        info = QLabel(
            "Нажмите «Изменить», затем нажмите нужную клавишу.\n"
            "Поддерживаются: F1–F12, буквы, Delete, Insert, Home, End и другие."
        )
        info.setStyleSheet("color: #8080aa; font-size: 11px;")
        info.setWordWrap(True)
        layout.addWidget(info)

        group = QGroupBox("Назначение клавиш")
        grid = QGridLayout(group)
        grid.setSpacing(10)
        grid.setColumnMinimumWidth(0, 220)

        rows = [
            ("Показать / скрыть панель", "hotkey_toggle_panel"),
            ("Click-through вкл / выкл", "hotkey_clickthrough"),
        ]
        self._btns = {}
        for i, (label, key) in enumerate(rows):
            btn = HotkeyButton(self.settings.get(key, ""))
            edit_btn = QPushButton("Изменить")
            edit_btn.setFixedWidth(80)
            edit_btn.clicked.connect(self._make_listen(btn))
            grid.addWidget(QLabel(label), i, 0)
            grid.addWidget(btn, i, 1)
            grid.addWidget(edit_btn, i, 2)
            self._btns[key] = btn
        layout.addWidget(group)

        row = QHBoxLayout()
        row.addStretch()
        ok_btn = QPushButton("Сохранить")
        ok_btn.setObjectName("accent")
        ok_btn.clicked.connect(self._save)
        cancel_btn = QPushButton("Отмена")
        cancel_btn.clicked.connect(self.reject)
        row.addWidget(ok_btn)
        row.addWidget(cancel_btn)
        layout.addLayout(row)

    def _make_listen(self, btn):
        def _do():
            btn.start_listen()
            btn.setFocus()
        return _do

    def _save(self):
        for key, btn in self._btns.items():
            txt = btn.text()
            if txt and txt != "Нажмите клавишу...":
                self.settings[key] = txt
        self.accept()


CROSSHAIR_MODES = [
    ("cross",       "Cross — крестообразный"),
    ("dot",         "Dot — точка"),
    ("ring",        "Ring — кольцо (dot without center)"),
    ("circle",      "Circle — окружность"),
    ("cross+dot",   "Cross + Dot"),
    ("circle+dot",  "Circle + Dot"),
    ("x",           "X — диагональный"),
    ("T",           "T-образный"),
    ("chevron",     "Chevron — галочка"),
    ("ngon3",       "Triangle — треугольник"),
]


class CrosshairSettingsWindow(QDialog):
    settings_changed = pyqtSignal()

    def __init__(self, settings, parent=None):
        super().__init__(parent)
        self.settings = settings
        self.setWindowTitle("Настройка прицела")
        self.setMinimumWidth(680)
        self.setWindowFlags(
            Qt.Window | (self.windowFlags() & ~Qt.WindowContextHelpButtonHint)
        )
        self.setStyleSheet(STYLE)
        self.setWindowIcon(get_app_icon())
        self._build()
        self._refresh_all()

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(18, 18, 18, 18)
        root.setSpacing(12)

        title = QLabel("Детальная настройка прицела")
        title.setStyleSheet("font-size: 15px; font-weight: bold; color: #9090ff; padding-bottom: 2px;")
        root.addWidget(title)

        content = QHBoxLayout()
        content.setSpacing(16)

        left = QVBoxLayout()
        left.setSpacing(10)

        shape_group = QGroupBox("Тип прицела")
        sg = QVBoxLayout(shape_group)
        self.mode_combo = QComboBox()
        for key, label in CROSSHAIR_MODES:
            self.mode_combo.addItem(label, key)
        self.mode_combo.currentIndexChanged.connect(self._on_mode)
        sg.addWidget(self.mode_combo)
        left.addWidget(shape_group)

        overlay_group = QGroupBox("Тип оверлея")
        og = QVBoxLayout(overlay_group)
        self.overlay_combo = QComboBox()
        for key, label in OVERLAY_TYPES.items():
            self.overlay_combo.addItem(label, key)
        self.overlay_combo.currentIndexChanged.connect(self._on_overlay)
        overlay_info = QLabel(
            "Real Overlay — для DirectX/fullscreen игр.\n"
            "Simple / Topmost — для обычных и оконных игр."
        )
        overlay_info.setStyleSheet("color: #8080aa; font-size: 10px;")
        overlay_info.setWordWrap(True)
        og.addWidget(self.overlay_combo)
        og.addWidget(overlay_info)
        left.addWidget(overlay_group)

        params_group = QGroupBox("Параметры формы")
        pg = QGridLayout(params_group)
        pg.setSpacing(8)
        pg.setColumnStretch(1, 1)

        self._spinboxes = {}
        param_defs = [
            ("Размер",            "size",              0.50, 200.0, 0.50),
            ("Толщина",           "thickness",         0.25,  20.0, 0.25),
            ("Зазор",             "gap",               0.00,  80.0, 0.50),
            ("Размер точки",      "dot_size",          0.25,  30.0, 0.25),
            ("Толщина обводки",   "outline_thickness", 0.25,  10.0, 0.25),
            ("Длина внеш. линий", "outline_ext_len",   0.50,  80.0, 0.50),
            ("Зазор внеш. линий", "outline_ext_gap",   0.00,  40.0, 0.25),
            ("Сдвиг X",           "x_offset",        -500.0, 500.0, 1.00),
            ("Сдвиг Y",           "y_offset",        -500.0, 500.0, 1.00),
        ]
        for i, (lbl, key, mn, mx, step) in enumerate(param_defs):
            sb = make_spinbox(self.settings.get(key, 0), mn, mx, 2, step, 115)
            sb.valueChanged.connect(self._make_handler(key))
            pg.addWidget(QLabel(lbl), i, 0)
            pg.addWidget(sb, i, 1)
            self._spinboxes[key] = sb
        left.addWidget(params_group)

        alpha_group = QGroupBox("Прозрачность прицела")
        ag = QHBoxLayout(alpha_group)
        self.alpha_slider = QSlider(Qt.Horizontal)
        self.alpha_slider.setRange(10, 255)
        self.alpha_slider.setValue(int(self.settings.get("alpha", 255)))
        self.alpha_lbl = QLabel(str(self.settings.get("alpha", 255)))
        self.alpha_lbl.setFixedWidth(30)
        self.alpha_lbl.setStyleSheet("color: #6868cc;")
        self.alpha_slider.valueChanged.connect(self._on_alpha)
        ag.addWidget(self.alpha_slider)
        ag.addWidget(self.alpha_lbl)
        left.addWidget(alpha_group)

        left.addStretch()
        content.addLayout(left, 3)

        right = QVBoxLayout()
        right.setSpacing(10)

        color_group = QGroupBox("Цвет")
        cg = QGridLayout(color_group)
        cg.setSpacing(8)
        cg.setColumnStretch(0, 1)

        self.color_btn = QPushButton()
        self.color_btn.setFixedSize(80, 30)
        self.color_btn.clicked.connect(self._pick_color)
        cg.addWidget(QLabel("Цвет прицела"), 0, 0)
        cg.addWidget(self.color_btn, 0, 1)

        self.outline_color_btn = QPushButton()
        self.outline_color_btn.setFixedSize(80, 30)
        self.outline_color_btn.clicked.connect(self._pick_outline_color)
        cg.addWidget(QLabel("Цвет обводки / внеш. линий"), 1, 0)
        cg.addWidget(self.outline_color_btn, 1, 1)

        right.addWidget(color_group)

        outline_group = QGroupBox("Обводка и внешние линии")
        outg = QVBoxLayout(outline_group)
        outg.setSpacing(7)

        self.outline_check = QCheckBox("Обводка (stroke вокруг прицела)")
        self.outline_check.toggled.connect(lambda v: self._set("outline", v))
        outg.addWidget(self.outline_check)

        self.outline_ext_check = QCheckBox("Внешние линии (за краями прицела)")
        self.outline_ext_check.toggled.connect(lambda v: self._set("outline_ext", v))
        outg.addWidget(self.outline_ext_check)

        right.addWidget(outline_group)

        flags_group = QGroupBox("Дополнительно")
        fg = QVBoxLayout(flags_group)
        fg.setSpacing(7)
        self.tshape_check = QCheckBox("T-shape (убрать верхнюю линию)")
        self.tshape_check.toggled.connect(lambda v: self._set("t_shape", v))
        self.cdot_check = QCheckBox("Центральная точка")
        self.cdot_check.toggled.connect(lambda v: self._set("center_dot", v))
        fg.addWidget(self.tshape_check)
        fg.addWidget(self.cdot_check)
        right.addWidget(flags_group)

        preview_group = QGroupBox("Предпросмотр")
        pvg = QVBoxLayout(preview_group)
        pvg.setAlignment(Qt.AlignCenter)
        self.preview = CrosshairPreview(self.settings)
        pvg.addWidget(self.preview, 0, Qt.AlignCenter)
        right.addWidget(preview_group)

        right.addStretch()
        content.addLayout(right, 2)
        root.addLayout(content)

        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet("color: #3a3a5c;")
        root.addWidget(sep)

        profile_group = QGroupBox("Сохранить как профиль")
        prg = QHBoxLayout(profile_group)
        prg.setSpacing(8)
        self.profile_name_input = QLineEdit()
        self.profile_name_input.setPlaceholderText("Введите название профиля...")
        save_btn = QPushButton("Сохранить профиль")
        save_btn.setObjectName("accent")
        save_btn.clicked.connect(self._save_profile)
        prg.addWidget(self.profile_name_input)
        prg.addWidget(save_btn)
        root.addWidget(profile_group)

        btn_row = QHBoxLayout()
        btn_row.addStretch()
        reset_btn = QPushButton("Сброс к умолчаниям")
        reset_btn.setObjectName("danger")
        reset_btn.clicked.connect(self._reset)
        close_btn = QPushButton("Закрыть")
        close_btn.clicked.connect(self.close)
        btn_row.addWidget(reset_btn)
        btn_row.addWidget(close_btn)
        root.addLayout(btn_row)

    def _make_handler(self, key):
        def handler(val):
            self.settings[key] = round(val, 2)
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()
        return handler

    def _set(self, key, val):
        self.settings[key] = val
        save_settings(self.settings)
        self.preview.update()
        self.settings_changed.emit()

    def _on_mode(self, idx):
        key = self.mode_combo.itemData(idx)
        if key:
            self.settings["mode"] = key
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()

    def _on_overlay(self, idx):
        key = self.overlay_combo.itemData(idx)
        if key:
            self.settings["overlay_type"] = key
            save_settings(self.settings)
            self.settings_changed.emit()

    def _on_alpha(self, val):
        self.settings["alpha"] = val
        self.alpha_lbl.setText(str(val))
        save_settings(self.settings)
        self.preview.update()
        self.settings_changed.emit()

    def _pick_color(self):
        c = QColorDialog.getColor(QColor(self.settings["color"]), self)
        if c.isValid():
            self.settings["color"] = c.name()
            self._update_color_btns()
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()

    def _pick_outline_color(self):
        c = QColorDialog.getColor(QColor(self.settings["outline_color"]), self)
        if c.isValid():
            self.settings["outline_color"] = c.name()
            self._update_color_btns()
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()

    def _on_outline(self, checked):
        self.settings["outline"] = checked
        save_settings(self.settings)
        self.preview.update()
        self.settings_changed.emit()

    def _update_color_btns(self):
        self.color_btn.setStyleSheet(
            f"background: {self.settings['color']}; border-radius: 4px; border: 1px solid #3a3a5c;"
        )
        self.outline_color_btn.setStyleSheet(
            f"background: {self.settings['outline_color']}; border-radius: 4px; border: 1px solid #3a3a5c;"
        )

    def _refresh_all(self):
        for key, sb in self._spinboxes.items():
            sb.blockSignals(True)
            sb.setValue(float(self.settings.get(key, 0)))
            sb.blockSignals(False)
        cur_mode = self.settings.get("mode", "cross")
        for i in range(self.mode_combo.count()):
            if self.mode_combo.itemData(i) == cur_mode:
                self.mode_combo.blockSignals(True)
                self.mode_combo.setCurrentIndex(i)
                self.mode_combo.blockSignals(False)
                break
        cur_ov = self.settings.get("overlay_type", "simple")
        for i in range(self.overlay_combo.count()):
            if self.overlay_combo.itemData(i) == cur_ov:
                self.overlay_combo.blockSignals(True)
                self.overlay_combo.setCurrentIndex(i)
                self.overlay_combo.blockSignals(False)
                break
        self.alpha_slider.blockSignals(True)
        self.alpha_slider.setValue(int(self.settings.get("alpha", 255)))
        self.alpha_slider.blockSignals(False)
        self.alpha_lbl.setText(str(self.settings.get("alpha", 255)))
        self.outline_check.blockSignals(True)
        self.outline_check.setChecked(bool(self.settings.get("outline", False)))
        self.outline_check.blockSignals(False)
        self.outline_ext_check.blockSignals(True)
        self.outline_ext_check.setChecked(bool(self.settings.get("outline_ext", False)))
        self.outline_ext_check.blockSignals(False)
        self.tshape_check.blockSignals(True)
        self.tshape_check.setChecked(bool(self.settings.get("t_shape", False)))
        self.tshape_check.blockSignals(False)
        self.cdot_check.blockSignals(True)
        self.cdot_check.setChecked(bool(self.settings.get("center_dot", False)))
        self.cdot_check.blockSignals(False)
        self._update_color_btns()
        self.preview.update()

    def notify_external_change(self):
        self._refresh_all()

    def _save_profile(self):
        name = self.profile_name_input.text().strip()
        if not name:
            QMessageBox.warning(self, "Ошибка", "Введите название профиля.")
            return
        profiles = self.settings.setdefault("profiles", {})
        if name in profiles:
            r = QMessageBox.question(
                self, "Перезаписать?",
                f'Профиль «{name}» уже существует. Перезаписать?',
                QMessageBox.Yes | QMessageBox.No
            )
            if r != QMessageBox.Yes:
                return
        profiles[name] = extract_profile(self.settings)
        self.settings["active_profile"] = name
        save_settings(self.settings)
        self.profile_name_input.clear()
        self.settings_changed.emit()
        QMessageBox.information(self, "Сохранено", f'Профиль «{name}» сохранён.')

    def _reset(self):
        r = QMessageBox.question(
            self, "Сброс настроек",
            "Сбросить настройки прицела к значениям по умолчанию?",
            QMessageBox.Yes | QMessageBox.No
        )
        if r == QMessageBox.Yes:
            for key in PROFILE_KEYS:
                if key in DEFAULT_SETTINGS:
                    self.settings[key] = DEFAULT_SETTINGS[key]
            save_settings(self.settings)
            self._refresh_all()
            self.settings_changed.emit()


class ProfileManagerDialog(QDialog):
    profile_loaded = pyqtSignal()

    def __init__(self, settings, parent=None):
        super().__init__(parent)
        self.settings = settings
        self.setWindowTitle("Профили прицела")
        self.setMinimumWidth(500)
        self.setMinimumHeight(420)
        self.setWindowFlags(self.windowFlags() & ~Qt.WindowContextHelpButtonHint)
        self.setStyleSheet(STYLE)
        self.setWindowIcon(get_app_icon())
        self._build()
        self._refresh_list()

    def _build(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(10)

        title = QLabel("Управление профилями прицела")
        title.setStyleSheet("font-size: 14px; font-weight: bold; color: #9090ff;")
        layout.addWidget(title)

        self.list_widget = QListWidget()
        self.list_widget.itemDoubleClicked.connect(self._load_selected)
        layout.addWidget(self.list_widget)

        self.active_lbl = QLabel("")
        self.active_lbl.setStyleSheet("color: #8080aa; font-size: 11px;")
        layout.addWidget(self.active_lbl)

        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet("color: #3a3a5c;")
        layout.addWidget(sep)

        save_group = QGroupBox("Сохранить текущий прицел как профиль")
        sg = QHBoxLayout(save_group)
        self.name_input = QLineEdit()
        self.name_input.setPlaceholderText("Название профиля...")
        save_btn = QPushButton("Сохранить")
        save_btn.setObjectName("accent")
        save_btn.clicked.connect(self._save_current)
        sg.addWidget(self.name_input)
        sg.addWidget(save_btn)
        layout.addWidget(save_group)

        btn_row = QHBoxLayout()
        load_btn = QPushButton("Загрузить")
        load_btn.setObjectName("accent")
        load_btn.clicked.connect(self._load_selected)
        delete_btn = QPushButton("Удалить")
        delete_btn.setObjectName("danger")
        delete_btn.clicked.connect(self._delete_selected)
        rename_btn = QPushButton("Переименовать")
        rename_btn.clicked.connect(self._rename_selected)
        close_btn = QPushButton("Закрыть")
        close_btn.clicked.connect(self.close)
        btn_row.addWidget(load_btn)
        btn_row.addWidget(delete_btn)
        btn_row.addWidget(rename_btn)
        btn_row.addStretch()
        btn_row.addWidget(close_btn)
        layout.addLayout(btn_row)

    def _refresh_list(self):
        self.list_widget.clear()
        profiles = self.settings.get("profiles", {})
        active = self.settings.get("active_profile", "")
        for name in profiles:
            item = QListWidgetItem(name)
            if name == active:
                item.setForeground(QColor("#9090ff"))
                item.setToolTip("Активный профиль")
            self.list_widget.addItem(item)
        self.active_lbl.setText(
            f"Активный профиль: {active}" if active else "Нет активного профиля"
        )

    def _current_name(self):
        item = self.list_widget.currentItem()
        return item.text() if item else None

    def _save_current(self):
        name = self.name_input.text().strip()
        if not name:
            QMessageBox.warning(self, "Ошибка", "Введите название профиля.")
            return
        profiles = self.settings.setdefault("profiles", {})
        if name in profiles:
            r = QMessageBox.question(
                self, "Перезаписать?",
                f'Профиль «{name}» уже существует. Перезаписать?',
                QMessageBox.Yes | QMessageBox.No
            )
            if r != QMessageBox.Yes:
                return
        profiles[name] = extract_profile(self.settings)
        self.settings["active_profile"] = name
        save_settings(self.settings)
        self.name_input.clear()
        self._refresh_list()
        self.profile_loaded.emit()

    def _load_selected(self):
        name = self._current_name()
        if not name:
            return
        profiles = self.settings.get("profiles", {})
        if name in profiles:
            self.settings.update(profiles[name])
            self.settings["active_profile"] = name
            save_settings(self.settings)
            self._refresh_list()
            self.profile_loaded.emit()

    def _delete_selected(self):
        name = self._current_name()
        if not name:
            return
        r = QMessageBox.question(
            self, "Удалить профиль",
            f'Удалить профиль «{name}»?',
            QMessageBox.Yes | QMessageBox.No
        )
        if r == QMessageBox.Yes:
            self.settings.get("profiles", {}).pop(name, None)
            if self.settings.get("active_profile") == name:
                self.settings["active_profile"] = ""
            save_settings(self.settings)
            self._refresh_list()
            self.profile_loaded.emit()

    def _rename_selected(self):
        name = self._current_name()
        if not name:
            return
        new_name, ok = _input_dialog(self, "Переименовать", "Новое название:", name)
        if ok and new_name.strip() and new_name.strip() != name:
            new_name = new_name.strip()
            profiles = self.settings.get("profiles", {})
            profiles[new_name] = profiles.pop(name)
            if self.settings.get("active_profile") == name:
                self.settings["active_profile"] = new_name
            save_settings(self.settings)
            self._refresh_list()


def _input_dialog(parent, title, label, default=""):
    dlg = QDialog(parent)
    dlg.setWindowTitle(title)
    dlg.setFixedWidth(340)
    dlg.setWindowFlags(dlg.windowFlags() & ~Qt.WindowContextHelpButtonHint)
    dlg.setStyleSheet(STYLE)
    layout = QVBoxLayout(dlg)
    layout.setContentsMargins(14, 14, 14, 14)
    layout.setSpacing(10)
    layout.addWidget(QLabel(label))
    inp = QLineEdit(default)
    layout.addWidget(inp)
    row = QHBoxLayout()
    row.addStretch()
    ok_btn = QPushButton("OK")
    ok_btn.setObjectName("accent")
    cancel_btn = QPushButton("Отмена")
    ok_btn.clicked.connect(dlg.accept)
    cancel_btn.clicked.connect(dlg.reject)
    row.addWidget(ok_btn)
    row.addWidget(cancel_btn)
    layout.addLayout(row)
    accepted = dlg.exec_() == QDialog.Accepted
    return inp.text(), accepted


class ControlPanel(QWidget):
    settings_changed = pyqtSignal()

    def __init__(self, settings):
        super().__init__()
        self.settings = settings
        self._xhair_win = None
        self._profile_win = None
        self.setWindowTitle(APP_NAME)
        self.setWindowFlags(Qt.WindowStaysOnTopHint | Qt.Tool)
        self.setFixedWidth(600)
        self.setStyleSheet(STYLE)
        self.setWindowIcon(get_app_icon())
        self._build()

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(16, 16, 16, 16)
        root.setSpacing(10)

        header = QHBoxLayout()
        title = QLabel(APP_NAME)
        title.setStyleSheet("font-size: 17px; font-weight: bold; color: #9090ff; letter-spacing: 1px;")
        header.addWidget(title)
        header.addStretch()
        self.active_profile_lbl = QLabel("")
        self.active_profile_lbl.setStyleSheet("color: #8080aa; font-size: 11px;")
        header.addWidget(self.active_profile_lbl)
        root.addLayout(header)

        sep = QFrame()
        sep.setFrameShape(QFrame.HLine)
        sep.setStyleSheet("color: #3a3a5c;")
        root.addWidget(sep)

        main_row = QHBoxLayout()
        main_row.setSpacing(14)

        left = QVBoxLayout()
        left.setSpacing(8)

        quick_group = QGroupBox("Быстрые настройки")
        qg = QGridLayout(quick_group)
        qg.setSpacing(8)
        qg.setColumnStretch(1, 1)

        self._spinboxes = {}
        quick_params = [
            ("Размер",   "size",      0.50, 200.0, 0.50),
            ("Толщина",  "thickness", 0.25,  20.0, 0.25),
            ("Зазор",    "gap",       0.00,  80.0, 0.50),
        ]
        for i, (lbl, key, mn, mx, step) in enumerate(quick_params):
            sb = make_spinbox(self.settings.get(key, 0), mn, mx, 2, step, 115)
            sb.valueChanged.connect(self._make_handler(key))
            qg.addWidget(QLabel(lbl), i, 0)
            qg.addWidget(sb, i, 1)
            self._spinboxes[key] = sb

        n = len(quick_params)
        self.mode_combo = QComboBox()
        for key, label in CROSSHAIR_MODES:
            self.mode_combo.addItem(label, key)
        cur = self.settings.get("mode", "cross")
        for i in range(self.mode_combo.count()):
            if self.mode_combo.itemData(i) == cur:
                self.mode_combo.setCurrentIndex(i)
                break
        self.mode_combo.currentIndexChanged.connect(self._on_mode)
        qg.addWidget(QLabel("Тип прицела"), n, 0)
        qg.addWidget(self.mode_combo, n, 1)

        self.color_btn = QPushButton()
        self.color_btn.setFixedSize(80, 28)
        self.color_btn.clicked.connect(self._pick_color)
        qg.addWidget(QLabel("Цвет"), n + 1, 0)
        qg.addWidget(self.color_btn, n + 1, 1, Qt.AlignLeft)

        self.overlay_combo = QComboBox()
        for key, label in OVERLAY_TYPES.items():
            self.overlay_combo.addItem(label, key)
        cur_ov = self.settings.get("overlay_type", "simple")
        for i in range(self.overlay_combo.count()):
            if self.overlay_combo.itemData(i) == cur_ov:
                self.overlay_combo.setCurrentIndex(i)
                break
        self.overlay_combo.currentIndexChanged.connect(self._on_overlay)
        qg.addWidget(QLabel("Overlay"), n + 2, 0)
        qg.addWidget(self.overlay_combo, n + 2, 1)

        left.addWidget(quick_group)
        left.addStretch()
        main_row.addLayout(left, 3)

        right = QVBoxLayout()
        right.setSpacing(8)
        preview_group = QGroupBox("Предпросмотр")
        pvg = QVBoxLayout(preview_group)
        pvg.setAlignment(Qt.AlignCenter)
        self.preview = CrosshairPreview(self.settings)
        pvg.addWidget(self.preview, 0, Qt.AlignCenter)
        right.addWidget(preview_group)
        right.addStretch()
        main_row.addLayout(right, 2)
        root.addLayout(main_row)

        sep2 = QFrame()
        sep2.setFrameShape(QFrame.HLine)
        sep2.setStyleSheet("color: #3a3a5c;")
        root.addWidget(sep2)

        actions_group = QGroupBox("Управление")
        ag = QGridLayout(actions_group)
        ag.setSpacing(8)

        xhair_btn = QPushButton("Настройка прицела...")
        xhair_btn.setObjectName("accent")
        xhair_btn.clicked.connect(self._open_xhair)
        ag.addWidget(xhair_btn, 0, 0)

        profiles_btn = QPushButton("Профили...")
        profiles_btn.clicked.connect(self._open_profiles)
        ag.addWidget(profiles_btn, 0, 1)

        self.ct_btn = QPushButton("Click-through: ВЫКЛ")
        self.ct_btn.setCheckable(True)
        ag.addWidget(self.ct_btn, 1, 0)

        hotkeys_btn = QPushButton("Горячие клавиши...")
        hotkeys_btn.clicked.connect(self._open_hotkeys)
        ag.addWidget(hotkeys_btn, 1, 1)

        hide_btn = QPushButton("Скрыть панель")
        hide_btn.clicked.connect(self.hide)
        ag.addWidget(hide_btn, 2, 0, 1, 2)

        root.addWidget(actions_group)
        self._update_color_btn()
        self._update_active_profile_lbl()
        self.adjustSize()

    def _make_handler(self, key):
        def handler(val):
            self.settings[key] = round(val, 2)
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()
            if self._xhair_win and self._xhair_win.isVisible():
                self._xhair_win.notify_external_change()
        return handler

    def _on_mode(self, idx):
        key = self.mode_combo.itemData(idx)
        if key:
            self.settings["mode"] = key
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()
            if self._xhair_win and self._xhair_win.isVisible():
                self._xhair_win.notify_external_change()

    def _on_overlay(self, idx):
        key = self.overlay_combo.itemData(idx)
        if key:
            self.settings["overlay_type"] = key
            save_settings(self.settings)
            self.settings_changed.emit()

    def _pick_color(self):
        c = QColorDialog.getColor(QColor(self.settings["color"]), self)
        if c.isValid():
            self.settings["color"] = c.name()
            self._update_color_btn()
            save_settings(self.settings)
            self.preview.update()
            self.settings_changed.emit()
            if self._xhair_win and self._xhair_win.isVisible():
                self._xhair_win.notify_external_change()

    def _update_color_btn(self):
        self.color_btn.setStyleSheet(
            f"background: {self.settings['color']}; border-radius: 4px; border: 1px solid #3a3a5c;"
        )

    def _update_active_profile_lbl(self):
        active = self.settings.get("active_profile", "")
        self.active_profile_lbl.setText(f"Профиль: {active}" if active else "")

    def _open_xhair(self):
        if self._xhair_win is None or not self._xhair_win.isVisible():
            self._xhair_win = CrosshairSettingsWindow(self.settings, self)
            self._xhair_win.settings_changed.connect(self._on_child_changed)
        self._xhair_win.show()
        self._xhair_win.activateWindow()
        self._xhair_win.raise_()

    def _open_profiles(self):
        if self._profile_win is None or not self._profile_win.isVisible():
            self._profile_win = ProfileManagerDialog(self.settings, self)
            self._profile_win.profile_loaded.connect(self._on_profile_loaded)
        self._profile_win.show()
        self._profile_win.activateWindow()
        self._profile_win.raise_()

    def _open_hotkeys(self):
        dlg = HotkeyDialog(self.settings, self)
        if dlg.exec_() == QDialog.Accepted:
            save_settings(self.settings)
            self.settings_changed.emit()

    def _on_child_changed(self):
        self._sync_quick()
        self.preview.update()
        self._update_active_profile_lbl()
        self.settings_changed.emit()

    def _on_profile_loaded(self):
        self._sync_quick()
        self.preview.update()
        self._update_active_profile_lbl()
        self.settings_changed.emit()
        if self._xhair_win and self._xhair_win.isVisible():
            self._xhair_win.notify_external_change()

    def _sync_quick(self):
        for key, sb in self._spinboxes.items():
            sb.blockSignals(True)
            sb.setValue(float(self.settings.get(key, 0)))
            sb.blockSignals(False)
        cur = self.settings.get("mode", "cross")
        for i in range(self.mode_combo.count()):
            if self.mode_combo.itemData(i) == cur:
                self.mode_combo.blockSignals(True)
                self.mode_combo.setCurrentIndex(i)
                self.mode_combo.blockSignals(False)
                break
        cur_ov = self.settings.get("overlay_type", "simple")
        for i in range(self.overlay_combo.count()):
            if self.overlay_combo.itemData(i) == cur_ov:
                self.overlay_combo.blockSignals(True)
                self.overlay_combo.setCurrentIndex(i)
                self.overlay_combo.blockSignals(False)
                break
        self._update_color_btn()

    def set_clickthrough(self, active):
        self.ct_btn.blockSignals(True)
        self.ct_btn.setChecked(active)
        self.ct_btn.setText(f"Click-through: {'ВКЛ' if active else 'ВЫКЛ'}")
        self.ct_btn.blockSignals(False)


class CrosshairApp:
    def __init__(self):
        self.app = QApplication(sys.argv)
        self.app.setQuitOnLastWindowClosed(False)
        self.app.setWindowIcon(get_app_icon())
        self.settings = load_settings()
        self.click_through = False

        self.crosshair = CrosshairWidget(self.settings)
        self.panel = ControlPanel(self.settings)
        self.panel.settings_changed.connect(self._on_changed)
        self.panel.ct_btn.clicked.connect(self._toggle_clickthrough)

        self._setup_tray()
        self._setup_hotkeys()
        self.panel.show()

        self._timer = QTimer()
        self._timer.timeout.connect(self.crosshair.recenter)
        self._timer.start(2000)

    def _setup_tray(self):
        self.tray = QSystemTrayIcon(self.app)
        tray_pix = get_tray_pixmap()
        self.tray.setIcon(QIcon(tray_pix))
        self.tray.setToolTip(APP_NAME)
        self._rebuild_tray_menu()
        self.tray.activated.connect(self._tray_activated)
        self.tray.show()

    def _rebuild_tray_menu(self):
        menu = QMenu()
        menu.setStyleSheet(STYLE)

        a = QAction("Показать панель", self.app)
        a.triggered.connect(self._show_panel)
        menu.addAction(a)

        a = QAction("Toggle click-through", self.app)
        a.triggered.connect(self._toggle_clickthrough)
        menu.addAction(a)

        menu.addSeparator()

        a = QAction("Настройка прицела...", self.app)
        a.triggered.connect(self._tray_open_xhair)
        menu.addAction(a)

        a = QAction("Профили...", self.app)
        a.triggered.connect(self._tray_open_profiles)
        menu.addAction(a)

        profiles = self.settings.get("profiles", {})
        if profiles:
            sub = QMenu("Выбрать профиль", menu)
            sub.setStyleSheet(STYLE)
            active = self.settings.get("active_profile", "")
            for name in profiles:
                label = f"{name}  [активный]" if name == active else name
                act = QAction(label, self.app)
                act.triggered.connect(self._make_profile_loader(name))
                sub.addAction(act)
            menu.addMenu(sub)

        a = QAction("Горячие клавиши...", self.app)
        a.triggered.connect(self._tray_open_hotkeys)
        menu.addAction(a)

        menu.addSeparator()

        a = QAction("Выход", self.app)
        a.triggered.connect(self._exit_app)
        menu.addAction(a)

        self.tray.setContextMenu(menu)

    def _make_profile_loader(self, name):
        def _load():
            profiles = self.settings.get("profiles", {})
            if name in profiles:
                self.settings.update(profiles[name])
                self.settings["active_profile"] = name
                save_settings(self.settings)
                self.crosshair.update()
                self.panel._sync_quick()
                self.panel.preview.update()
                self.panel._update_active_profile_lbl()
                if self.panel._xhair_win and self.panel._xhair_win.isVisible():
                    self.panel._xhair_win.notify_external_change()
                self._rebuild_tray_menu()
                self.tray.showMessage(
                    APP_NAME, f'Загружен профиль: {name}',
                    QSystemTrayIcon.Information, 1500
                )
        return _load

    def _tray_activated(self, reason):
        if reason == QSystemTrayIcon.DoubleClick:
            self._show_panel()

    def _show_panel(self):
        self.panel.show()
        self.panel.activateWindow()
        self.panel.raise_()

    def _tray_open_xhair(self):
        self._show_panel()
        self.panel._open_xhair()

    def _tray_open_profiles(self):
        self._show_panel()
        self.panel._open_profiles()

    def _tray_open_hotkeys(self):
        dlg = HotkeyDialog(self.settings)
        if dlg.exec_() == QDialog.Accepted:
            save_settings(self.settings)
            self._register_hotkeys()

    def _setup_hotkeys(self):
        self.signals = HotkeySignals()
        self.signals.toggle_panel.connect(self._toggle_panel)
        self.signals.toggle_clickthrough.connect(self._toggle_clickthrough)
        self._register_hotkeys()

    def _register_hotkeys(self):
        try:
            keyboard.unhook_all()
        except Exception:
            pass
        try:
            keyboard.add_hotkey(
                self.settings.get("hotkey_toggle_panel", "F8"),
                lambda: self.signals.toggle_panel.emit()
            )
            keyboard.add_hotkey(
                self.settings.get("hotkey_clickthrough", "F9"),
                lambda: self.signals.toggle_clickthrough.emit()
            )
        except Exception:
            pass

    def _toggle_panel(self):
        if self.panel.isVisible():
            self.panel.hide()
        else:
            self._show_panel()

    def _toggle_clickthrough(self):
        self.click_through = not self.click_through
        self.panel.set_clickthrough(self.click_through)
        msg = "ВКЛ" if self.click_through else "ВЫКЛ"
        self.tray.showMessage(
            APP_NAME, f"Click-through: {msg}",
            QSystemTrayIcon.Information, 1000
        )

    def _on_changed(self):
        ot = self.settings.get("overlay_type", "simple")
        if ot != getattr(self, "_last_overlay_type", None):
            self._last_overlay_type = ot
            self.crosshair.reload_overlay()
        else:
            self.crosshair.update()
        self._rebuild_tray_menu()

    def _exit_app(self):
        save_settings(self.settings)
        try:
            keyboard.unhook_all()
        except Exception:
            pass
        self.tray.hide()
        self.app.quit()

    def run(self):
        sys.exit(self.app.exec_())


if __name__ == "__main__":
    app = CrosshairApp()
    app.run()
